SELECT DISTINCTROW [Рабочий-для-ввода].NAME, [Рабочий-для-ввода].YEAR, [Рабочий-для-ввода].NUST, [Рабочий-для-ввода].E, [Рабочий-для-ввода].EOTP, [Рабочий-для-ввода].EURT, [Рабочий-для-ввода].EUST, [Рабочий-для-ввода].Q, [Рабочий-для-ввода].TURT, [Рабочий-для-ввода].TUST, [Рабочий-для-ввода].B, [Рабочий-для-ввода].GAZ, [Рабочий-для-ввода].MAZUT, [Рабочий-для-ввода].UGOL, [Рабочий-для-ввода].RAICH AS Выражение1, [Рабочий-для-ввода].PRIM, [Рабочий-для-ввода].URG, [Рабочий-для-ввода].LUCH, [Рабочий-для-ввода].NER AS Выражение2, [Рабочий-для-ввода].BUR, [Рабочий-для-ввода].IRKUT, [Рабочий-для-ввода].KAN, [Рабочий-для-ввода].CHIT, [Рабочий-для-ввода].MAG, [Рабочий-для-ввода].SAH, [Рабочий-для-ввода].PROCH, [Рабочий-для-ввода].QOTR, [Рабочий-для-ввода].SNK, [Рабочий-для-ввода].EWTP, [Рабочий-для-ввода].NT, IIf([comp]=1,[numb],[main]) AS numbm, Имена_станций.ordnumb, [Рабочий-для-ввода].SNt, [Рабочий-для-ввода].NUMB1120
FROM [Рабочий-для-ввода] INNER JOIN Имена_станций ON [Рабочий-для-ввода].NUMB1120=Имена_станций.NUMB
WHERE ((([Рабочий-для-ввода].OES)=7 Or ([Рабочий-для-ввода].OES)=9))
ORDER BY Имена_станций.ordnumb;
